import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/academy/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"CollectionPage","name":"Pubrica Academy","url":"https://pubrica.com/academy/","description":"Free guidance on writing a paper, appraising one, interpreting an analysis and satisfying journal, university and funder rules.","inLanguage":"en","isPartOf":{"@type":"WebSite","name":"Pubrica","url":"https://pubrica.com/"},"publisher":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Is any of this behind a sign-up?","acceptedAnswer":{"@type":"Answer","text":"No. Every article and resource on Academy is open, with no account, no email address and no gated download. The same applies to the twelve free tools. If a page ever asks you for a detail before it will show you an answer, it is a mistake and we would like to know about it."}},{"@type":"Question","name":"Some categories have very few articles.","acceptedAnswer":{"@type":"Answer","text":"Two of the four are well populated and two are still being written, and the pages say which is which rather than padding the list. We would rather show you four real articles than forty titles that lead nowhere. If there is a topic you want covered, tell us — most of what is here was commissioned because a reader asked."}},{"@type":"Question","name":"When will the templates and flow charts be available?","acceptedAnswer":{"@type":"Answer","text":"They are being produced now. The libraries are published with their structure and naming so you can see what is coming and tell us what is missing, and each item says whether it is ready. Nothing is listed as a download until the file exists, because a broken promise is worse than a short list."}},{"@type":"Question","name":"Who writes these?","acceptedAnswer":{"@type":"Answer","text":"The subject matter experts of Pubrica who do the work itself — the information specialist who builds the searches, the statistician who runs the analyses, the medical writers who write to the guidelines. A guide on responding to reviewers is written by somebody who drafts rebuttals."}},{"@type":"Question","name":"Are the guides kept current?","acceptedAnswer":{"@type":"Answer","text":"Yes, and that is why they carry the standard they teach to rather than only a date. When CONSORT moved to its 2025 edition, the guides written against CONSORT 2010 were revised rather than left up with a note."}},{"@type":"Question","name":"Will you write my paper if I take a course?","acceptedAnswer":{"@type":"Answer","text":"Those are separate things and we keep them separate. Academy teaches you to do the work; the services do the work with you named as the author throughout. We do not offer ghost authorship in either direction, and a course is not a route into one."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Pubrica Academy","item":"https://pubrica.com/academy/"}]}];

